do $$ begin if not exists (select 1 from pg_type t join pg_enum e on e.enumtypid=t.oid where t.typname='analytics_event_type' and e.enumlabel='review_replied') then alter type public.analytics_event_type add value 'review_replied'; end if; end $$;
create or replace function public.business_reply_review(p_business_id uuid,p_review_id uuid,p_reply text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_review reviews; begin if not public.business_admin_allowed(p_business_id) then raise exception 'Admin access required'; end if; if nullif(trim(p_reply),'') is null then raise exception 'Reply cannot be empty'; end if; if length(trim(p_reply))>2000 then raise exception 'Reply is too long'; end if; update reviews r set business_reply=trim(p_reply),business_replied_at=now(),updated_at=now() where r.id=p_review_id and exists(select 1 from locations l where l.id=r.location_id and l.business_id=p_business_id) returning r.* into v_review; if not found then raise exception 'Review not found or not owned by business'; end if; insert into analytics_events(event_type,business_id,location_id,user_id,metadata,created_at) values('review_replied',p_business_id,v_review.location_id,auth.uid(),jsonb_build_object('review_id',v_review.id,'test_data',false),now()); return to_jsonb(v_review); end $$;
